<?php
require_once 'config/app.php';require_roles(['admin','pimpinan']);$pageTitle='Persetujuan Pimpinan';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)$_POST['id'];$aksi=$_POST['aksi'];$q=$pdo->prepare("SELECT * FROM peminjaman WHERE id=?");$q->execute([$id]);$p=$q->fetch();if($p&&$p['status']==='Menunggu Persetujuan'&&in_array($aksi,['setuju','tolak'])){$new=$aksi==='setuju'?'Disetujui':'Ditolak';$pdo->prepare("UPDATE peminjaman SET status=?,disetujui_oleh=?,catatan=? WHERE id=?")->execute([$new,current_user()['nama'],trim($_POST['catatan']),$id]);log_status($pdo,$id,$p['status'],$new,trim($_POST['catatan']));if($new==='Disetujui')$pdo->prepare("UPDATE kendaraan SET status='Dipinjam' WHERE id=?")->execute([$p['kendaraan_id']]);flash('Pengajuan '.$new.'.');}redirect('persetujuan.php');}
$rows=$pdo->query("SELECT p.*,g.nama,k.merk,k.nomor_polisi FROM peminjaman p JOIN pegawai g ON g.id=p.pegawai_id JOIN kendaraan k ON k.id=p.kendaraan_id WHERE p.status='Menunggu Persetujuan' ORDER BY p.id")->fetchAll();require 'includes/header.php';?>
<h3 class="mb-3">Persetujuan Pimpinan</h3><div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Nomor</th><th>Peminjam</th><th>Kendaraan</th><th>Jadwal</th><th>Keperluan</th><th>Keputusan</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nomor_peminjaman'])?></td><td><?=e($r['nama'])?></td><td><?=e($r['merk'].' '.$r['nomor_polisi'])?></td><td><?=e(date('d/m/Y H:i',strtotime($r['tanggal_pinjam'])))?> – <?=e(date('d/m/Y H:i',strtotime($r['tanggal_kembali_rencana'])))?></td><td><?=e($r['keperluan'].'; '.$r['tujuan'])?></td><td><form method="post" class="d-flex gap-1 flex-wrap"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input name="catatan" class="form-control form-control-sm" placeholder="Catatan"><button name="aksi" value="setuju" class="btn btn-sm btn-success" onclick="return confirm('Setujui pengajuan ini?')">Setujui</button><button name="aksi" value="tolak" class="btn btn-sm btn-danger" onclick="return confirm('Tolak pengajuan ini?')">Tolak</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="text-center p-4 text-muted">Tidak ada pengajuan menunggu persetujuan.</td></tr><?php endif;?></tbody></table></div></div><?php require 'includes/footer.php';?>